files.content:
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #a0a0b0;
  --border: #0f3460;
  --shadow: #0a0a1a;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: 'Courier New', Courier, monospace;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  font-size: 16px;
  line-height: 1.5;
  image-rendering: pixelated;
}

.card {
  background: var(--card);
  border: 4px solid var(--border);
  box-shadow: 8px 8px 0 var(--shadow);
  padding: 24px;
  width: 100%;
  max-width: 400px;
}

h1 {
  font-size: 1.5rem;
  text-align: center;
  margin-bottom: 24px;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
  text-shadow: 2px 2px 0 var(--shadow);
}

.field {
  margin-bottom: 20px;
}

label {
  display: block;
  margin-bottom: 6px;
  font-size: 0.9rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 1px;
}

input[type="number"] {
  width: 100%;
  padding: 12px;
  font-family: inherit;
  font-size: 1rem;
  background: var(--bg);
  color: var(--text);
  border: 3px solid var(--border);
  outline: none;
  transition: border-color 0.1s, box-shadow 0.1s;
}

input[type="number"]:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(233, 69, 96, 0.3);
}

input[type="number"]::-webkit-inner-spin-button,
input[type="number"]::-webkit-outer-spin-button {
  opacity: 1;
}

.tip-group {
  border: none;
  margin-bottom: 20px;
}

.tip-group legend {
  font-size: 0.9rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 6px;
}

.tip-buttons {
  display: flex;
  gap: 8px;
}

.tip-btn {
  flex: 1;
  padding: 12px 0;
  font-family: inherit;
  font-size: 1rem;
  font-weight: bold;
  background: var(--bg);
  color: var(--text);
  border: 3px solid var(--border);
  cursor: pointer;
  transition: background 0.1s, transform 0.05s, border-color 0.1s;
  box-shadow: 3px 3px 0 var(--shadow);
}

.tip-btn:hover {
  border-color: var(--accent);
  background: #1f2a4a;
}

.tip-btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.tip-btn:active {
  transform: translate(2px, 2px);
  box-shadow: 1px 1px 0 var(--shadow);
}

.tip-btn.selected {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
}

.results {
  border-top: 3px dashed var(--border);
  padding-top: 16px;
  margin-top: 8px;
}

.result-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding: 8px 0;
  font-size: 1rem;
}

.result-row span:first-child {
  color: var(--muted);
}

.result-value {
  font-weight: bold;
  font-size: 1.25rem;
  color: var(--accent);
  text-shadow: 1px 1px 0 var(--shadow);
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
  }
  .tip-buttons {
    flex-direction: column;
  }
  .tip-btn {
    padding: 10px 0;
  }
}

(function () {
  'use strict';

  const billInput = document.getElementById('bill');
  const peopleInput = document.getElementById('people');
  const tipButtons = document.querySelectorAll('.tip-btn');
  const tipPerPersonEl = document.getElementById('tipPerPerson');
  const totalPerPersonEl = document.getElementById('totalPerPerson');

  let selectedTip = 0;

  function formatCurrency(value) {
    return '$' + value.toFixed(2);
  }

  function calculate() {
    const bill = parseFloat(billInput.value) || 0;
    let people = parseInt(peopleInput.value, 10);
    if (isNaN(people) || people < 1) {
      people = 1;
    }
    const tipAmount = bill * (selectedTip / 100);
    const total = bill + tipAmount;
    const tipPerPerson = tipAmount / people;
    const totalPerPerson = total / people;

    tipPerPersonEl.textContent = formatCurrency(tipPerPerson);
    totalPerPersonEl.textContent = formatCurrency(totalPerPerson);
  }

  function setTip(percent, button) {
    selectedTip = percent;
    tipButtons.forEach(function (btn) {
      const isSelected = btn === button;
      btn.classList.toggle('selected', isSelected);
      btn.setAttribute('aria-pressed', isSelected ? 'true' : 'false');
    });
    calculate();
  }

  tipButtons.forEach(function (btn) {
    btn.addEventListener('click', function () {
      const percent = parseInt(btn.dataset.tip, 10);
      setTip(percent, btn);
    });
  });

  billInput.addEventListener('input', calculate);
  peopleInput.addEventListener('input', calculate);

  // Initialize with default values
  calculate();
})();
